function numberGame(nums) {
  // Play the game literally: find and remove the minimum twice per round.
  const pool = nums.slice();
  const arr = [];
  const takeMin = () => {
    let at = 0;
    for (let j = 1; j < pool.length; j++) if (pool[j] < pool[at]) at = j;
    return pool.splice(at, 1)[0];
  };
  while (pool.length > 0) {
    const alice = takeMin();
    const bob = takeMin();
    arr.push(bob);
    arr.push(alice);
  }
  return arr;
}

