function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = 2 * int(1, 4);
    const top = rand() < 0.3 ? 3 : 100;
    return [Array.from({ length: n }, () => int(1, top))];
  }
  const top = rand() < 0.5 ? 100 : 10;
  return [Array.from({ length: 100 }, () => int(1, top))];
}
